namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int CentsFor(LoyaltyTier tier, int subtotalCents)
    {
        var points = Math.Min(BasePoints(tier) + BonusPoints(subtotalCents), CeilingPoints);

        return subtotalCents * points / 100;
    }

    private static int BasePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9
    };

    private static int BonusPoints(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
python3 - <<'E'
p='src/CheckoutPricing.Application/CalculatePayableTotal.cs'
s=open(p).read().replace("return subtotalCents;","return subtotalCents - LoyaltyDiscount.CentsFor(tier, subtotalCents);")
open(p,'w').write(s)
E
dotnet test 2>&1 | grep -E "warning|error|Passed!|Failed!"|sort -u

